const sourcesHtml = id => {
  const list = (SOURCES[id] || []).map(k => SRC[k]).filter(Boolean);
  if (!list.length) return '';
  const link = ([url, label]) => `<a class="ext" href="${url}" target="_blank" rel="noopener">${label}</a>`;
  return `<div class="sources"><b>📚 Источники</b><ul>${list.map(([text, links]) =>
    `<li>${text}${links.length ? ' ' + links.map(link).join(' · ') : ''}</li>`).join('')}</ul></div>`;
};

const photosHtml = id => {
  const list = PHOTOS[id];
  if (!list) return '';
  return `<div class="photos"><b>🖼 Фото на Wikimedia Commons:</b> ${list.map(([q, label]) =>
    `<a class="ext" href="https://commons.wikimedia.org/w/index.php?search=${encodeURIComponent(q)}&title=Special:MediaSearch&type=image" target="_blank" rel="noopener">${label}</a>`).join(' · ')}</div>`;
};

